// The flags the games draw from, picked by hand so nothing in them is a remix, a meme or a fan flag.
// `flag` is the flag's name on Vexilo (for links), `image` is its path on the CDN.
//
// Countries also carry what the grid asks about. Anything marked ~ is accepted when a player guesses it
// but never counted when a grid is built, so every square has answers no one could argue with.
//   regions  AF Africa · AS Asia · EU Europe · NA North America · SA South America · OC Oceania
//   colours  r red · b blue · g green · y yellow or gold · w white · k black · o orange · p purple
//   traits   st star · cr crescent · su sun · x cross or saltire · hs horizontal stripes · vs vertical stripes
//            tr triangle · dg diagonal · ca coat of arms or seal · an animal · pl plant · wp weapon · tx writing
//            ci circle · uj Union Jack · cn canton · mp map · ot other emblem

export type CountryRow = { id: string; name: string; flag: string; image: string; region: string; colors: string; traits: string };
export type PlaceRow = { id: string; name: string; flag: string; image: string; set: string };

